        next_c = field_storage.CTRL.wflush.value;
        load_next_c = '0;
        if(decoded_reg_strb.CTRL && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.CTRL.wflush.value & ~decoded_wr_biten[0:0]) | (decoded_wr_data[0:0] & decoded_wr_biten[0:0]);
            load_next_c = '1;
        end
        field_combo.CTRL.wflush.next = next_c;
        field_combo.CTRL.wflush.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge arst_n) begin
        if(~arst_n) begin
            field_storage.CTRL.wflush.value <= 1'h0;
        end else begin
            if(field_combo.CTRL.wflush.load_next) begin
                field_storage.CTRL.wflush.value <= field_combo.CTRL.wflush.next;
            end
        end
    end
    assign hwif_out.CTRL.wflush.value = field_storage.CTRL.wflush.value;
    // Field: axil_mailbox.CTRL.rflush
    always_comb begin
        automatic logic [0:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.CTRL.rflush.value;
        load_next_c = '0;
        if(decoded_reg_strb.CTRL && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.CTRL.rflush.value & ~decoded_wr_biten[1:1]) | (decoded_wr_data[1:1] & decoded_wr_biten[1:1]);
            load_next_c = '1;
        end
        field_combo.CTRL.rflush.next = next_c;
        field_combo.CTRL.rflush.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge arst_n) begin
        if(~arst_n) begin
            field_storage.CTRL.rflush.value <= 1'h0;
        end else begin
            if(field_combo.CTRL.rflush.load_next) begin
                field_storage.CTRL.rflush.value <= field_combo.CTRL.rflush.next;
            end
        end
    end
    assign hwif_out.CTRL.rflush.value = field_storage.CTRL.rflush.value;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic [6:0] rd_mux_addr;
    assign rd_mux_addr = decoded_addr;

    logic readback_err;
    logic readback_done;
    logic [63:0] readback_data;
    always_comb begin
        automatic logic [63:0] readback_data_var;
        readback_data_var = '0;
        if(rd_mux_addr == 7'h8) begin
            readback_data_var[63:0] = 64'h0;
        end
        if(rd_mux_addr == 7'h10) begin
            readback_data_var[0] = 1'h0;
            readback_data_var[1] = 1'h0;
            readback_data_var[2] = 1'h0;
            readback_data_var[3] = 1'h0;
        end
        if(rd_mux_addr == 7'h18) begin
            readback_data_var[0] = 1'h0;
            readback_data_var[1] = 1'h0;
        end
        if(rd_mux_addr == 7'h20) begin
            readback_data_var[7:0] = field_storage.WIRQT.wirqt.value;
        end
        if(rd_mux_addr == 7'h28) begin
            readback_data_var[7:0] = field_storage.RIRQT.rirqt.value;
        end
        if(rd_mux_addr == 7'h30) begin
            readback_data_var[0] = field_storage.IRQS.wtirq.value;
            readback_data_var[1] = field_storage.IRQS.rtirq.value;
            readback_data_var[2] = field_storage.IRQS.eirq.value;
        end
        if(rd_mux_addr == 7'h38) begin
            readback_data_var[0] = field_storage.IRQEN.wtirq.value;
            readback_data_var[1] = field_storage.IRQEN.rtirq.value;
            readback_data_var[2] = field_storage.IRQEN.eirq.value;
        end
        if(rd_mux_addr == 7'h40) begin
            readback_data_var[0] = 1'h0;
            readback_data_var[1] = 1'h0;
            readback_data_var[2] = 1'h0;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
